import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Techy News — Comprehensive Project Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}`),a={name:`guide/introduction.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="techy-news-—-comprehensive-project-guide" tabindex="-1">Techy News — Comprehensive Project Guide <a class="header-anchor" href="#techy-news-—-comprehensive-project-guide" aria-label="Permalink to &quot;Techy News — Comprehensive Project Guide&quot;">​</a></h1><p>Welcome to the internal documentation for <strong>Techy News</strong>. This guide provides a full overview of the codebase, project structure, and operational procedures.</p><h2 id="🏗-technology-stack" tabindex="-1">🏗 Technology Stack <a class="header-anchor" href="#🏗-technology-stack" aria-label="Permalink to &quot;🏗 Technology Stack&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li><strong>Laravel 13</strong>: Modern PHP framework for rapid, secure development.</li><li><strong>Eloquent ORM</strong>: Fluent database interactions.</li><li><strong>MySQL</strong>: Persistent data storage for articles, subscribers, and analytics.</li><li><strong>Inertia.js</strong>: The &quot;glue&quot; that allows us to build a single-page app experience using classic server-side routing.</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><strong>React 18</strong>: Component-based UI library.</li><li><strong>Vite</strong>: Ultra-fast build tool and development server.</li><li><strong>Tailwind CSS</strong>: Utility-first CSS framework for rapid UI building.</li><li><strong>Framer Motion</strong>: industry-standard animation library for React.</li><li><strong>Lucide React</strong>: Clean and consistent icon set.</li></ul><h3 id="ai-services" tabindex="-1">AI &amp; Services <a class="header-anchor" href="#ai-services" aria-label="Permalink to &quot;AI &amp; Services&quot;">​</a></h3><ul><li><strong>Gemini 2.0 Flash</strong>: State-of-the-art LLM from Google for article synthesis and translation.</li><li><strong>NewsService</strong>: Aggregates data from global RSS feeds.</li></ul><h2 id="📂-project-structure" tabindex="-1">📂 Project Structure <a class="header-anchor" href="#📂-project-structure" aria-label="Permalink to &quot;📂 Project Structure&quot;">​</a></h2><ul><li><code>app/</code>: The core PHP logic. <ul><li><code>Http/Controllers/</code>: Request handling and response coordination.</li><li><code>Services/</code>: Business logic (Gemini integration, RSS parsing).</li><li><code>Models/</code>: Database schema definitions.</li></ul></li><li><code>resources/js/</code>: The React frontend. <ul><li><code>Pages/</code>: High-level page components (Welcome, ArticleShow, Archive).</li><li><code>Components/</code>: Reusable UI elements (Navbar, LanguageSwitcher).</li><li><code>Hooks/</code>: Custom React hooks (useLanguage).</li></ul></li><li><code>docs/</code>: Comprehensive project documentation.</li><li><code>database/migrations/</code>: Database schema versioning.</li></ul><h2 id="⚙️-core-workflows" tabindex="-1">⚙️ Core Workflows <a class="header-anchor" href="#⚙️-core-workflows" aria-label="Permalink to &quot;⚙️ Core Workflows&quot;">​</a></h2><h3 id="_1-the-content-lifecycle" tabindex="-1">1. The Content Lifecycle <a class="header-anchor" href="#_1-the-content-lifecycle" aria-label="Permalink to &quot;1. The Content Lifecycle&quot;">​</a></h3><p>Articles are generated through a semi-automated pipeline:</p><ol><li>RSS feeds are fetched via <code>NewsService</code>.</li><li>Gemini analyzes headlines and suggests editorial ideas.</li><li>A draft is generated in raw HTML and saved to the database.</li><li>On first request in a new language, the translation engine kicks in.</li></ol><h3 id="_2-multi-language-support" tabindex="-1">2. Multi-language Support <a class="header-anchor" href="#_2-multi-language-support" aria-label="Permalink to &quot;2. Multi-language Support&quot;">​</a></h3><p>We support <strong>English (en)</strong>, <strong>Spanish (es)</strong>, and <strong>Portuguese (pt)</strong>.</p><ul><li>Translations are handled via <code>es.json</code>, <code>pt.json</code>, etc.</li><li>Database articles have a <code>translations</code> JSON column for content-specific overrides.</li></ul><h3 id="_3-frontend-theme-system" tabindex="-1">3. Frontend Theme System <a class="header-anchor" href="#_3-frontend-theme-system" aria-label="Permalink to &quot;3. Frontend Theme System&quot;">​</a></h3><ul><li>The project supports <strong>Light</strong> and <strong>Dark</strong> modes.</li><li>Theme state is managed via a dedicated component (<code>ThemeToggle.jsx</code>) and persisted in <code>localStorage</code>.</li><li>We use Tailwind&#39;s <code>dark:</code> modifier extensively.</li></ul><h2 id="🛠-maintenance-development" tabindex="-1">🛠 Maintenance &amp; Development <a class="header-anchor" href="#🛠-maintenance-development" aria-label="Permalink to &quot;🛠 Maintenance &amp; Development&quot;">​</a></h2><h3 id="local-development" tabindex="-1">Local Development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local Development&quot;">​</a></h3><ol><li>Run <code>php artisan serve</code> for the backend.</li><li>Run <code>npm run dev</code> for the frontend.</li><li>Access the dashboard at <code>/dashboard</code> to manage articles.</li></ol><h3 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h3><ul><li>Every push to <code>main</code> triggers a GitHub Action.</li><li>The action builds assets and deploys via <code>rsync</code> to the production server.</li></ul><h2 id="📋-best-practices" tabindex="-1">📋 Best Practices <a class="header-anchor" href="#📋-best-practices" aria-label="Permalink to &quot;📋 Best Practices&quot;">​</a></h2><ul><li><strong>Content Security</strong>: Always use <code>sanitizeContent()</code> before rendering raw HTML from the database.</li><li><strong>Performance</strong>: Use Laravel&#39;s <code>Cache</code> facade for any expensive AI or database operations.</li><li><strong>Translations</strong>: Always wrap user-facing strings in the <code>__()</code> helper.</li></ul>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};